var spoitems = {};
var product_unit_prices = {};
var product_unit_conversions = {};
var product_units = typeof product_units !== 'undefined' ? product_units : {};
var all_units = typeof all_units !== 'undefined' ? all_units : {};

function add_order_item(item) {
    var item_id = Settings.item_addition == 1 ? item.item_id : item.id;
    var product_id = item.id || item.item_id || item.row.id;

    // ✅ Fix empty fields
    if (!item.row.id) item.row.id = product_id;
    if (!item.row.code) item.row.code = item.code || '';
    if (!item.row.name) item.row.name = item.label || '';

    // Store units, prices, and conversions
    if (item.units) product_units[product_id] = item.units;
    if (item.unit_prices) product_unit_prices[product_id] = item.unit_prices;
    if (item.unit_conversions) product_unit_conversions[product_id] = item.unit_conversions;

    // Default quantities for dual-unit
    if (item.row.is_dual_unit == 1) {
        //item.row.qty = item.row.qty || 0;
        item.row.primary_qty = item.row.primary_qty || 0;
        item.row.secondary_qty = item.row.secondary_qty || 0;
        item.row.secondary_qty = item.row.secondary_qty || 0;
        item.row.primary_unit = item.row.primary_unit || item.row.base_unit_id;
        item.row.secondary_unit = item.row.secondary_unit || 0;
    } else {
        //item.row.qty = item.row.qty || 0;
        item.row.primary_qty = item.row.primary_qty || 0;
        item.row.secondary_qty = item.row.secondary_qty || 0;
        item.row.unit_id = item.row.unit_id || item.row.base_unit_id;
    }

    spoitems[item_id] = item;
    store('spoitems', JSON.stringify(spoitems));
    loadItems();
}


function loadItems() {
    if (get('spoitems')) {
        spoitems = JSON.parse(get('spoitems'));
        var total = 0;
        $("#poTable tbody").empty();

        $.each(spoitems, function () {
            var item = this;
            var item_id = Settings.item_addition == 1 ? item.item_id : item.id;
            var product_id = item.row.id;
            var item_cost = parseFloat(item.row.cost) || 0;
            var primary_qty = parseFloat(item.row.primary_qty) || 0;
            var secondary_qty = parseFloat(item.row.secondary_qty) || 0;
            var transportation = parseFloat(item.row.transportation) || 0;

            // Build unit dropdowns
            var primaryOptions = '';
            var secondaryOptions = '';

            if (product_units[product_id]) {
                $.each(product_units[product_id], function (id, name) {
                    var selected_primary = (item.row.primary_unit == id) ? "selected" : "";
                    var selected_secondary = (item.row.secondary_unit == id) ? "selected" : "";
                    primaryOptions += '<option value="' + id + '" ' + selected_primary + '>' + name + '</option>';
                    secondaryOptions += '<option value="' + id + '" ' + selected_secondary + '>' + name + '</option>';
                });
            }

            // Fallback for base unit
            if (!primaryOptions && item.row.base_unit_id) {
                primaryOptions = '<option value="' + item.row.base_unit_id + '" selected>Unit</option>';
            }
            if (!secondaryOptions && item.row.secondary_unit) {
                secondaryOptions = '<option value="' + item.row.secondary_unit + '" selected>Unit</option>';
            }

            // Build table row
            var row_no = new Date().getTime();
            var newTr = $('<tr id="' + row_no + '" data-item-id="' + item_id + '" data-id="' + product_id + '"></tr>');
            var tr_html = '<td><input type="hidden" name="product_id[]" value="' + product_id + '">' + (item.row.name || '-') + ' (' + (item.row.code || '-') + ')</td>';

            if (item.row.is_dual_unit && item.row.is_dual_unit > 0) {
                tr_html += '<td><input type="number" class="form-control primary_qty" name="primary_qty[]" step="any" min="0" value="' + primary_qty + '"></td>';
                tr_html += '<td><select name="primary_unit[]" class="form-control">' + primaryOptions + '</select></td>';
                tr_html += '<td><input type="number" class="form-control secondary_qty" name="secondary_qty[]" step="any" min="0" value="' + secondary_qty + '"></td>';
                tr_html += '<td><select name="secondary_unit[]" class="form-control">' + secondaryOptions + '</select></td>';
            } else {
                tr_html += '<td><input type="number" class="form-control primary_qty" name="primary_qty[]" value="' + primary_qty + '" step="any" min="0"></td>';
                tr_html += '<td><select name="primary_unit[]" class="form-control">' + primaryOptions + '</select></td>';
                tr_html += '<td><input type="hidden" name="secondary_qty[]" value="0" step="any" min="0">-</td>';
                tr_html += '<td><input type="hidden" name="secondary_unit[]" value="0" step="any" min="0">-</td>';
            }

            tr_html += '<td><input type="text" class="form-control rcost" name="cost[]" value="' + item_cost + '" step="any" min="0"></td>';

            var subtotal = $('.edit-po-form').length ? primary_qty * item_cost : (primary_qty + secondary_qty) * item_cost;
            tr_html += '<td class="text-right"><span class="ssubtotal">' + subtotal.toFixed(2) + '</span></td>';
            if (!$('.edit-po-form').length) tr_html += '<td><input type="text" class="form-control transportation" name="transportation[]" value="' + transportation + '"></td>';
            tr_html += '<td class="text-center"><i class="fa fa-trash spodel" data-item-id="' + item_id + '"></i></td>';

            newTr.html(tr_html);
            $("#poTable tbody").prepend(newTr);

            total += subtotal;
        });

        $("#gtotal").text(total.toFixed(2));
        if (!$('.edit-po-form').length) $('#advance_deducted').val(total.toFixed(2));
        else calculateGrandTotal();
    }
}


// Calculate subtotal for an item
function calculateItemSubtotal(item, product_id) {
    var cost = parseFloat(item.row.cost) || 0;
    var subtotal = 0;
    if ($(".edit-po-form").length) return (parseFloat(item.row.primary_qty) || 0) * cost;

    if (item.row.is_dual_unit == 1) {
        // Dual unit → only primary_qty counts for subtotal
        //var primary_qty = parseFloat(item.row.qty || 0);
        var primary_qty = parseFloat(item.row.primary_qty || 0);
        subtotal = primary_qty * cost;
    } else {
        // Single unit → use base qty (with conversion if needed)
        var base_qty = 0;
        var qty = parseFloat(item.row.primary_qty || 0);
        var unit = item.row.unit || '';

        if (product_unit_conversions[product_id] && product_unit_conversions[product_id][unit]) {
            base_qty = qty * parseFloat(product_unit_conversions[product_id][unit].value || 1);
        } else {
            base_qty = qty;
        }

        subtotal = base_qty * cost;
    }

    return subtotal;
}

function calculateTransport() {
    var transport_total = 0;

    $.each(spoitems, function (item_id, item) {
        var transport_cost = parseFloat(item.row.transportation) || 0;
        transport_total += transport_cost;
    });

    return transport_total;
}





// Quantity or unit change handler
$(document).on("change keyup", '.rquantity, .primary_qty, .secondary_qty, .rcost, .pos-unit, .transportation, .edit-po-form select[name="primary_unit[]"], .edit-po-form select[name="secondary_unit[]"]', function () {
    var row = $(this).closest('tr');
    var item_id = row.data('item-id');
    var product_id = row.data('id');

    if (row.find('.primary_qty').length) {
        //spoitems[item_id].row.qty = parseFloat(row.find('.primary_qty').val()) || 0;
        spoitems[item_id].row.primary_qty = parseFloat(row.find('.primary_qty').val()) || 0;
        spoitems[item_id].row.secondary_qty = parseFloat(row.find('.secondary_qty').val()) || 0;
        spoitems[item_id].row.secondary_qty = parseFloat(row.find('.secondary_qty').val()) || 0;
        spoitems[item_id].row.primary_unit = row.find('select[name="primary_unit[]"]').val();
        spoitems[item_id].row.secondary_unit = row.find('select[name="secondary_unit[]"]').val();
    } else {
        spoitems[item_id].row.primary_qty = parseFloat(row.find('.rquantity').val()) || 0;
        spoitems[item_id].row.unit_id = row.find('select[name="unit[]"]').val();
    }

    spoitems[item_id].row.cost = parseFloat(row.find('.rcost').val()) || 0;
    spoitems[item_id].row.transportation = parseFloat(row.find('.transportation').val()) || 0;
    store('spoitems', JSON.stringify(spoitems));

    var subtotal = calculateItemSubtotal(spoitems[item_id], product_id);
    var transportation = calculateTransport(); // 👈 no need to pass single item
    if (!$('.edit-po-form').length) $('#delivery').val(formatDecimal(transportation));
    row.find('.ssubtotal').text(formatMoney(subtotal)).attr('data-subtotal', subtotal);
    calculateGrandTotal();
});

// Recalculate grand total
function calculateGrandTotal() {
    var total = 0;

    $.each(spoitems, function (item_id, item) {
        total += calculateItemSubtotal(item, item.row.id);
    });

    if ($('.edit-po-form').length) total += parseFloat($('#delivery').val()) || 0;
    $('#gtotal').text(formatMoney(total));
    if (!$('.edit-po-form').length) $('#advance_deducted').val(formatDecimal(total));

    return total;
}


// Document ready
$(document).ready(function () {
    loadItems();
    $("#date").inputmask("yyyy-mm-dd hh:mm", { "placeholder": "yyyy-mm-dd hh:mm" });

    // Remove item
    $(document).on('click', '.spodel', function () {
        var row = $(this).closest('tr');
        var item_id = row.attr('data-item-id');
        delete spoitems[item_id];
        row.remove();
        localStorage.setItem('spoitems', JSON.stringify(spoitems));
        loadItems();
    });

    // Autocomplete
    $("#add_item").autocomplete({
        source: base_url + 'purchases/suggestions',
        minLength: 1,
        autoFocus: false,
        delay: 200,
        response: function (event, ui) {
            if ($(this).val().length >= 16 && ui.content[0].id == 0) {
                bootbox.alert(lang.no_match_found);
                $(this).val('');
            } else if (ui.content.length === 1 && ui.content[0].id !== 0) {
                ui.item = ui.content[0];
                $(this).data('ui-autocomplete')._trigger('select', 'autocompleteselect', ui);
                $(this).autocomplete('close');
            } else if (ui.content.length === 1 && ui.content[0].id === 0) {
                bootbox.alert(lang.no_match_found);
                $(this).val('');
            }
        },
        select: function (t, e) {
            (t.preventDefault(), 0 !== e.item.id) ? add_order_item(e.item) && $(this).val("") : bootbox.alert(lang.no_match_found);
        },
    });

    $('#add_item').on('keypress', function (e) {
        if (e.keyCode == 13) {
            e.preventDefault();
            $(this).autocomplete("search");
        }
    });

    $('#add_item').focus();

    // Reset
    $('#reset').click(function () {
        bootbox.confirm(lang.r_u_sure, function (result) {
            if (result) {
                remove('spoitems');
                window.location.reload();
            }
        });
    });
});

$(document).on("input change", ".edit-po-form #delivery", calculateGrandTotal);
